// The packaged pronunciation dictionary: its self-describing format, and the SHIPPED FILE
// itself. The second half matters more than it looks — the asset is generated by
// scripts/gen-voice-lexicon.mjs, which is run once in a blue moon, so nothing else would
// notice a regenerated file that decodes to the wrong phones until users heard it.

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { gunzipSync, gzipSync } from 'node:zlib';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseLexicon } from './lexicon.js';
import { arpaToIpa } from './arpabet.js';

const ASSET = join(dirname(fileURLToPath(import.meta.url)), '../../../public/voice/lexicon.txt.gz');

describe('parseLexicon', () => {
  test('decodes entries against the alphabet in the header', () => {
    // The codes are `0x21 + index`, so AA1 is `!`, T is `"` and K is `#`.
    const lex = parseLexicon(['# codes\tAA1 T K', 'cat\t#!"', 'tot\t"!"'].join('\n'));
    assert.deepEqual(lex.lookup('cat'), ['K', 'AA1', 'T']);
    assert.deepEqual(lex.lookup('tot'), ['T', 'AA1', 'T']);
    assert.equal(lex.size, 2);
  });

  test('a word it does not have is null, not an empty pronunciation', () => {
    const lex = parseLexicon(['# codes\tAA1 T', 'a\t!'].join('\n'));
    assert.equal(lex.lookup('b'), null);
    assert.deepEqual(lex.lookup('a'), ['AA1']);
  });

  // Decoding against a guessed alphabet would mispronounce every word in the dictionary
  // while looking like it worked, which is worse than not loading at all.
  test('refuses a file with no codes header', () => {
    assert.throws(() => parseLexicon('cat\t!!!'), /no "# codes" header/);
  });
});

// Found by running the app in a real browser, which is the only place it happens:
// Chrome serves an extension's own files verbatim, so the crx really does hand us gzip —
// but `vite dev` sees the `.gz` suffix, sets `Content-Encoding: gzip`, and the browser has
// already decompressed the body by the time we see it. Gunzipping that a second time
// throws, and the app loses its whole dictionary in development while working when packed.
describe('loadLexicon over the wire', () => {
  const FIXTURE = ['# codes\tAA1 T K', 'cat\t#!"'].join('\n');
  const withFetch = async (body: BodyInit): Promise<number> => {
    const original = globalThis.fetch;
    globalThis.fetch = (async () => new Response(body, { status: 200 })) as typeof fetch;
    try {
      // Bust the module's memoized promise between cases.
      const { loadLexicon } = (await import(`./lexicon.js?case=${Math.random()}`)) as typeof import('./lexicon.js');
      return (await loadLexicon()).size;
    } finally {
      globalThis.fetch = original;
    }
  };

  test('decompresses a body that is still gzip — the packed extension', async () => {
    const gz = gzipSync(Buffer.from(FIXTURE, 'utf8'));
    assert.equal(await withFetch(new Uint8Array(gz)), 1);
  });

  test('accepts a body the transport already decompressed — the dev server', async () => {
    assert.equal(await withFetch(FIXTURE), 1);
  });
});

describe('the shipped asset', () => {
  const text = gunzipSync(readFileSync(ASSET)).toString('utf8');
  const lexicon = parseLexicon(text);

  test('holds the whole dictionary', () => {
    assert.equal(lexicon.size > 120_000, true, `only ${lexicon.size} words`);
  });

  test('carries its provenance in the header, because the licence requires it', () => {
    assert.match(text, /CMU Pronouncing Dictionary/);
    assert.match(text, /BSD-2-Clause/);
    assert.match(text, /THIRD-PARTY-NOTICES/);
  });

  // Spot-checks against eSpeak-NG's own transcriptions, captured before the GPL
  // dependency was removed. If a regeneration ever shifts the encoding, these break.
  test('common words decode to the IPA Kokoro expects', () => {
    const say = (w: string): string => arpaToIpa(lexicon.lookup(w) ?? []);
    assert.equal(say('quick'), 'kwˈɪk');
    assert.equal(say('brown'), 'bɹˈaʊn');
    assert.equal(say('water'), 'wˈɔːɾɚ');
    assert.equal(say('church'), 'tʃˈɜːtʃ');
    assert.equal(say('going'), 'ɡˈoʊɪŋ');
  });

  test('every entry decodes to phones the mapping knows', () => {
    // A code with no phone behind it would silently drop a sound from a word.
    for (const word of ['pronunciation', 'extraordinary', 'rhythm', 'queue', 'strengths']) {
      const phones = lexicon.lookup(word);
      assert.notEqual(phones, null, word);
      assert.equal(arpaToIpa(phones ?? []).length > 0, true, word);
    }
  });
});
